glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  v_uv = a_texCoord;
  v_color = a_color;
  return cc_matViewProj * pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision mediump float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform CRTParams {
  vec2 resolution;
  float scanlineIntensity;
  float vignetteIntensity;
  float chromaticAberration;
  float curvature;
  vec2 _padding;
};
vec2 applyCurvature(vec2 uv) {
  vec2 centered = uv * 2.0 - 1.0;
  vec2 offset = centered * centered;
  centered *= 1.0 + offset.yx * curvature;
  return centered * 0.5 + 0.5;
}
vec4 frag () {
  vec2 curvedUV = applyCurvature(v_uv);
  if (curvedUV.x < 0.0 || curvedUV.x > 1.0 || curvedUV.y < 0.0 || curvedUV.y > 1.0) {
    return vec4(0.0, 0.0, 0.0, 1.0);
  }
  vec3 color;
  vec2 centerDist = abs(curvedUV - 0.5);
  float edgeFactor = max(centerDist.x, centerDist.y) * 2.0;
  if (edgeFactor > 0.5 && chromaticAberration > 0.0001) {
    float shift = chromaticAberration * edgeFactor;
    float r = texture(cc_spriteTexture, curvedUV + vec2(shift, 0.0)).r;
    float g = texture(cc_spriteTexture, curvedUV).g;
    float b = texture(cc_spriteTexture, curvedUV - vec2(shift, 0.0)).b;
    color = vec3(r, g, b);
  } else {
    color = texture(cc_spriteTexture, curvedUV).rgb;
  }
  float scanlineCount = resolution.y / 2.5;
  float scanlinePos = curvedUV.y * scanlineCount;
  float scanline = fract(scanlinePos);
  scanline = smoothstep(0.0, 0.5, scanline) - smoothstep(0.5, 1.0, scanline);
  float scanlineDarkening = 1.0 - scanlineIntensity * (1.0 - scanline);
  color *= scanlineDarkening;
  float flicker = 0.98 + 0.02 * sin(cc_time.x * 50.0);
  color *= flicker;
  vec2 vignetteUV = curvedUV - 0.5;
  float vignette = 1.0 - dot(vignetteUV, vignetteUV) * vignetteIntensity * 2.0;
  color *= max(vignette, 0.3);
  return vec4(color, 1.0) * v_color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

